agent_detail.agent_sql:
SELECT (COUNT(*) AS ?n)
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> .
}

SELECT ?claimNumber (SUM(?amt) AS ?totalExpensePayment)
WHERE {
  ?ep a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpensePayment> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpensePayment/claim_amount_identifier> ?caId .
  ?ca a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
  ?c a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
     <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
     <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claimNumber .
}
GROUP BY ?claimNumber
ORDER BY ?claimNumber

SELECT ?company_claim_number (SUM(?amt) AS ?totalLossAmount)
WHERE {
  {
    ?lp a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caid .
  }
  UNION
  {
    ?lr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossReserve> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caid .
  }
  ?ca a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caid ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
}
GROUP BY ?company_claim_number
ORDER BY ?company_claim_number

SELECT ?policy_number ?agent_id WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agent_id ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?policy .
  ?policy <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .
}
ORDER BY ?policy_number ?agent_id

SELECT ?claim_identifier ?company_claim_number ?claim_close_date WHERE {
  ?c a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
     <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claim_identifier ;
     <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number ;
     <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_close_date> ?claim_close_date .
  FILTER(STRSTARTS(STR(?claim_close_date), "2019"))
}

SELECT ?claim_number (SUM(?amt) AS ?totalLoss)
WHERE {
  ?ca a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caid ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .

  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claim_number .

  {
    ?lp a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caid .
  } UNION {
    ?lr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossReserve> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caid .
  } UNION {
    ?ep a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpensePayment> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpensePayment/claim_amount_identifier> ?caid .
  } UNION {
    ?er a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpenseReserve> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpenseReserve/claim_amount_identifier> ?caid .
  }
}
GROUP BY ?claim_number
ORDER BY ?claim_number

SELECT ((SUM(?amt)) / (COUNT(DISTINCT ?pid)) AS ?avgPolicySize)
WHERE {
  ?premium a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Premium> ;
           <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Premium/policy_amount_identifier> ?paid .
  ?pa a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount/policy_amount_identifier> ?paid ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount/policy_identifier> ?pid ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount/policy_amount> ?amt .
}

SELECT ?agentId ?policyNumber ?claimId ?catastropheName
WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agentId ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policyId .

  ?policy a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_identifier> ?policyId ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policyNumber .

  ?pcd a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/policy_identifier> ?policyId ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/policy_coverage_detail_identifier> ?pcdId .

  ?cc a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/policy_coverage_detail_identifier> ?pcdId ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/claim_identifier> ?claimId .

  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/catastrophe_identifier> ?catId .

  ?cat a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Catastrophe> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Catastrophe/catastrophe_identifier> ?catId ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Catastrophe/catastrophe_name> ?catastropheName .
}

SELECT ?agent_id (COUNT(DISTINCT ?policy) AS ?policyCount) WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> ?role ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agent_id ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policy .
  FILTER(?role = "AG")
}
GROUP BY ?agent_id
ORDER BY ?agent_id

SELECT ?policy_number (AVG(?days) AS ?avg_days_to_settle)
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_open_date> ?open ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_close_date> ?close .

  ?cc a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/policy_coverage_detail_identifier> ?pcdId .

  ?pcd a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/policy_coverage_detail_identifier> ?pcdId ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/policy_identifier> ?policyId .

  ?policy a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_identifier> ?policyId ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .

  FILTER(BOUND(?open) && BOUND(?close))

  BIND((xsd:date(?close) - xsd:date(?open)) AS ?days)
}
GROUP BY ?policy_number
ORDER BY ?policy_number

SELECT DISTINCT ?policy_number ?claim_number WHERE {
  ?cc a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim .

  ?pcd <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .

  ?policy <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .

  ?claim <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claim_number .
}
ORDER BY ?policy_number ?claim_number

SELECT ?party_identifier ?policy_number ?company_claim_number ?claim_amount
WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?party_identifier ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?policy .

  ?policy a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .

  ?pcd a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .

  ?cc a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim .

  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .

  ?ca a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?claim_amount .

  ?lp a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment/hasClaimAmount> ?ca .
}

SELECT ?policy_identifier ?party_identifier WHERE {
  ?policy a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_identifier> ?policy_identifier .
  ?role a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policy_identifier ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> ?role_code ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?party_identifier .
  FILTER(?role_code = "PH")
}

SELECT ?policy_number (AVG(?totalLoss) AS ?avgLoss)
WHERE {
  {
    SELECT ?policy_number ?policyId (SUM(?amt) AS ?totalLoss)
    WHERE {
      {
        ?lp a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment> ;
            <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caid .
      }
      UNION
      {
        ?lr a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossReserve> ;
            <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caid .
      }
      UNION
      {
        ?ep a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpensePayment> ;
            <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpensePayment/claim_amount_identifier> ?caid .
      }
      UNION
      {
        ?er a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpenseReserve> ;
            <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ExpenseReserve/claim_amount_identifier> ?caid .
      }

      ?ca a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caid ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId .

      ?cc a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/claim_identifier> ?claimId ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/ClaimCoverage/policy_coverage_detail_identifier> ?pcdId .

      ?pcd a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
           <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/policy_coverage_detail_identifier> ?pcdId ;
           <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyCoverageDetail/policy_identifier> ?policyId .

      ?p a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_identifier> ?policyId ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .
    }
    GROUP BY ?policy_number ?policyId
  }
}
GROUP BY ?policy_number

SELECT ?policy_number (SUM(?amt) AS ?totalPremium) WHERE {
  ?policy a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_identifier> ?pid ;
          <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .
  ?pa a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount> ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount/policy_identifier> ?pid ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount/policy_amount_identifier> ?paid ;
      <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/PolicyAmount/policy_amount> ?amt .
  ?prem a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Premium> ;
        <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Premium/policy_amount_identifier> ?paid .
}
GROUP BY ?policy_number
ORDER BY ?policy_number

SELECT ?claim_number ?catastrophe_name ?policy_number (SUM(?amt) AS ?total_loss)
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20260807-131754/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claim_id ;
